def web_search_exa(query, numResults=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    crawl_jobs = _load("crawl_jobs.json")
    crawl_documents = _load("crawl_documents.json")

    def _pick_active_key():
        active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # Prefer a key that has positive quota and rate_limit_rps
        def score(k):
            q = k.get("quota_requests_per_day", 0) if isinstance(k.get("quota_requests_per_day"), int) else 0
            r = k.get("rate_limit_rps", 0.0) if isinstance(k.get("rate_limit_rps"), (int, float)) else 0.0
            return (q > 0, r > 0, k.get("updated_at") or "", k.get("created_at") or "")
        active.sort(key=score, reverse=True)
        return active[0]

    def _utc_day_bounds(dt):
        d = dt.date()
        start = datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            # Accept 'Z'
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _rate_limited(key_id, rate_limit_rps):
        if not isinstance(rate_limit_rps, (int, float)) or rate_limit_rps <= 0:
            return False
        window = 1.0
        cutoff = now - datetime.timedelta(seconds=window)
        n = 0
        for r in search_requests:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if created and created >= cutoff:
                n += 1
        for j in crawl_jobs:
            if not isinstance(j, dict):
                continue
            if j.get("api_key_id") != key_id:
                continue
            created = _parse_dt(j.get("created_at"))
            if created and created >= cutoff:
                n += 1
        return n >= float(rate_limit_rps)

    def _quota_exceeded(key_row):
        qpd = key_row.get("quota_requests_per_day")
        if not isinstance(qpd, int) or qpd < 0:
            qpd = 0
        start, end = _utc_day_bounds(now)
        cnt = 0
        for r in search_requests:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != key_row.get("id"):
                continue
            created = _parse_dt(r.get("created_at"))
            if created and start <= created < end:
                cnt += 1
        for j in crawl_jobs:
            if not isinstance(j, dict):
                continue
            if j.get("api_key_id") != key_row.get("id"):
                continue
            created = _parse_dt(j.get("created_at"))
            if created and start <= created < end:
                cnt += 1
        return cnt >= qpd, cnt, qpd

    def _normalize_num_results(nr):
        if nr is None:
            nr = 5
        if isinstance(nr, bool) or not isinstance(nr, (int, float)):
            return None, _err("VALIDATION_ERROR", "numResults must be a positive number.")
        if nr != nr or nr in (float("inf"), float("-inf")):
            return None, _err("VALIDATION_ERROR", "numResults must be a finite positive number.")
        nr_int = int(nr)
        if nr_int < 1:
            return None, _err("VALIDATION_ERROR", "numResults must be a positive number.")
        if nr_int > 50:
            nr_int = 50
        return nr_int, None

    def _validate_query(q):
        if not isinstance(q, str):
            return _err("VALIDATION_ERROR", "query is required and must be a non-empty string.")
        if not q.strip():
            return _err("VALIDATION_ERROR", "query is required and must be a non-empty string.")
        return None

    # Validate inputs first
    e = _validate_query(query)
    if e:
        return e
    nr, e = _normalize_num_results(numResults)
    if e:
        return e

    # Resolve ambient auth: pick a usable active key
    key = _pick_active_key()
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")
    if key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")

    # Enforce rate limit and daily request quota BEFORE persisting the request
    if _rate_limited(key.get("id"), key.get("rate_limit_rps")):
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    exceeded, used, limit = _quota_exceeded(key)
    if exceeded:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", used=used, limit=limit)

    # Persist search_request + results
    req_id = "sr_" + uuid.uuid4().hex
    created_at = now_iso
    req_row = {
        "id": req_id,
        "api_key_id": key.get("id"),
        "tool_name": "web_search_exa",
        "vertical": "web",
        "query": query.strip(),
        "company_name": None,
        "industry": None,
        "search_type": None,
        "num_results_requested": nr,
        "status": "running",
        "error_code": None,
        "error_message": None,
        "upstream_request_id": "up_" + uuid.uuid4().hex,
        "started_at": now_iso,
        "finished_at": None,
        "latency_ms": None,
        "results_count": None,
        "created_at": created_at,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)

    # Generate deterministic-ish placeholder results from query tokens (offline)
    def _slug(s):
        s = s.lower()
        s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
        return s or "result"
    base = _slug(query.strip())[:60]
    results = []
    for i in range(1, nr + 1):
        url = f"https://example.com/search/{base}/{i}"
        domain = "example.com"
        row_id = "res_" + uuid.uuid4().hex
        results.append({
            "id": row_id,
            "search_request_id": req_id,
            "rank": i,
            "url": url,
            "domain": domain,
            "title": f"{query.strip()} — Result {i}",
            "snippet": f"Offline normalized snippet for '{query.strip()}' (rank {i}).",
            "published_at": None,
            "author": None,
            "source_type": "web",
            "entity_metadata": None,
            "relevance_score": float(max(0.0, 1.0 - (i - 1) * 0.03)),
            "created_at": now_iso,
            "updated_at": now_iso,
        })
    # Enforce unique(search_request_id, rank)
    existing_ranks = set()
    for r in search_results:
        if isinstance(r, dict) and r.get("search_request_id") == req_id:
            existing_ranks.add(r.get("rank"))
    for r in results:
        if r["rank"] in existing_ranks:
            # Extremely unlikely; treat as conflict
            req_row["status"] = "failed"
            req_row["error_code"] = "CONFLICT"
            req_row["error_message"] = "Duplicate result rank conflict."
            req_row["finished_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()
            req_row["updated_at"] = req_row["finished_at"]
            req_row["latency_ms"] = int((time.time() - t0) * 1000)
            _save("search_requests.json", search_requests)
            return _err("CONFLICT", "Duplicate rank for search_request_id.")
    search_results.extend(results)

    # Mark request succeeded
    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    req_row["status"] = "succeeded"
    req_row["finished_at"] = finished.isoformat()
    req_row["updated_at"] = req_row["finished_at"]
    req_row["latency_ms"] = int((time.time() - t0) * 1000)
    req_row["results_count"] = nr

    # Update key last_used_at/updated_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break

    _save("api_keys.json", api_keys)
    _save("search_requests.json", search_requests)
    _save("search_results.json", search_results)
    # Ensure other collections remain consistent if present; no writes needed
    return {
        "request": req_row,
        "results": results,
        "meta": {"num_results": nr}
    }

