def crawling_exa(url, maxCharacters=None, **_extra):
    import json, os, datetime, time, secrets
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None
    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        # stable enough for local datastore uniqueness
        ms = int(_now().timestamp() * 1000)
        return f"{prefix}_{ms:x}_{secrets.token_hex(8)}"

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string")
    u = url.strip()
    try:
        pu = urlparse(u)
        if pu.scheme not in ("http", "https") or not pu.netloc:
            return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")
    except Exception:
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")

    if maxCharacters is None:
        mc = 3000
    else:
        if not isinstance(maxCharacters, (int, float)) or isinstance(maxCharacters, bool):
            return _err("VALIDATION_ERROR", "maxCharacters must be a positive number when provided")
        if maxCharacters <= 0:
            return _err("VALIDATION_ERROR", "maxCharacters must be a positive number when provided")
        mc = int(maxCharacters)

    # Service validates/clamps to [256, 100000]
    if mc < 256:
        mc = 256
    if mc > 100000:
        mc = 100000

    api_keys = _load("api_keys.json")
    crawl_jobs = _load("crawl_jobs.json")
    crawl_documents = _load("crawl_documents.json")

    # Ambient authentication: pick any active key that can serve the call (exists + active)
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request")

    # Choose the key with the highest remaining daily request capacity (best-effort)
    now = _now()
    day0 = _utc_day_start(now)
    def _count_requests_for_key_today(key_id):
        c = 0
        for r in crawl_jobs:
            if isinstance(r, dict) and r.get("api_key_id") == key_id:
                dt = _parse_dt(r.get("created_at"))
                if dt and _utc_day_start(dt) == day0:
                    c += 1
        return c

    chosen = None
    best_remaining = None
    for k in active_keys:
        q = k.get("quota_requests_per_day")
        rps = k.get("rate_limit_rps")
        if not isinstance(q, int) or q < 0:
            continue
        if not isinstance(rps, (int, float)) or isinstance(rps, bool) or rps <= 0:
            continue
        used = _count_requests_for_key_today(k["id"])
        remaining = q - used
        if remaining <= 0:
            continue
        if best_remaining is None or remaining > best_remaining:
            chosen = k
            best_remaining = remaining

    if not chosen:
        # If keys exist but all are quota exhausted, return QUOTA_EXCEEDED (not NOT_FOUND)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for all available active API keys")

    # Rate limit: soft RPS check based on existing crawl_jobs created_at (local approximation)
    rps = float(chosen.get("rate_limit_rps"))
    window = 1.0
    recent = 0
    for r in crawl_jobs:
        if isinstance(r, dict) and r.get("api_key_id") == chosen["id"]:
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if (now - dt).total_seconds() < window:
                recent += 1
    if recent >= max(1, int(rps)):
        return _err("RATE_LIMIT", "Rate limit exceeded; please retry later")

    # Create crawl job (this tool is expected to be "synchronous", but still persisted)
    now_iso = _iso(now)
    job_id = _gen_id("exa_crawl")
    job = {
        "id": job_id,
        "api_key_id": chosen["id"],
        "url": u,
        "max_characters": mc,
        "status": "succeeded",
        "http_status": 200,
        "content_type": "text/html",
        "charset": "utf-8",
        "error_code": None,
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Generate deterministic-ish extracted content (offline) so URL is "retrievable" rather than failing NOT_FOUND
    text = (f"Extracted content (offline simulation) for {u}\n\n"
            f"This datastore-backed service cannot fetch live URLs. "
            f"The returned content is generated locally to preserve API semantics.\n")
    text_content = text[:mc]
    chars = len(text_content)

    # Enforce daily extraction character quota transactionally at write-time
    # (sum crawl_documents.characters_extracted per UTC day)
    quota_chars = chosen.get("quota_chars_extracted_per_day")
    if not isinstance(quota_chars, int) or quota_chars < 0:
        return _err("UNAUTHORIZED", "API key is misconfigured for character quota")
    used_chars = 0
    for d in crawl_documents:
        if isinstance(d, dict):
            cj_id = d.get("crawl_job_id")
            if not isinstance(cj_id, str):
                continue
            # join to crawl_jobs to verify key ownership and date
            parent = next((r for r in crawl_jobs if isinstance(r, dict) and r.get("id") == cj_id), None)
            if not parent or parent.get("api_key_id") != chosen["id"]:
                continue
            dt = _parse_dt(d.get("created_at") or parent.get("created_at"))
            if dt and _utc_day_start(dt) == day0:
                ce = d.get("characters_extracted")
                if isinstance(ce, int) and ce >= 0:
                    used_chars += ce
    if used_chars + chars > quota_chars:
        return _err("QUOTA_EXCEEDED", "Daily extracted character quota exceeded for this API key")

    # Persist job + doc
    doc_id = _gen_id("exa_doc")
    doc = {
        "id": doc_id,
        "crawl_job_id": job_id,
        "final_url": u,
        "title": None,
        "meta_description": None,
        "text_content": text_content,
        "excerpt": (text_content[:200] if text_content else None),
        "language": "en",
        "outbound_links": None,
        "structured_data": None,
        "characters_extracted": chars,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    crawl_jobs.append(job)
    crawl_documents.append(doc)

    # Update api key last_used_at
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == chosen["id"]:
            api_keys[i] = chosen
            break

    _save("crawl_jobs.json", crawl_jobs)
    _save("crawl_documents.json", crawl_documents)
    _save("api_keys.json", api_keys)

    job_out = dict(job)
    job_out["document"] = doc

    return {
        "crawl_job": job_out,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def competitor_finder_exa(companyName, industry=None, numResults=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        try:
            if isinstance(s, datetime.datetime):
                return s.astimezone(datetime.timezone.utc)
            if isinstance(s, str):
                # accept trailing Z
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None
        return None

    def _day_key(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_key(api_keys):
        # Ambient auth: choose any active key that can serve (exists and not suspended/revoked)
        for k in api_keys:
            if k.get("status") == "active":
                return k
        return None

    def _count_daily_requests(search_reqs, crawl_jobs, api_key_id, day):
        c = 0
        for r in search_reqs:
            if r.get("api_key_id") == api_key_id:
                dt = _parse_dt(r.get("created_at"))
                if dt and _day_key(dt) == day:
                    c += 1
        for j in crawl_jobs:
            if j.get("api_key_id") == api_key_id:
                dt = _parse_dt(j.get("created_at"))
                if dt and _day_key(dt) == day:
                    c += 1
        return c

    def _count_daily_chars(crawl_jobs, crawl_docs, api_key_id, day):
        # Sum characters_extracted for docs whose job belongs to key and doc created that day (UTC)
        job_ids = set()
        for j in crawl_jobs:
            if j.get("api_key_id") == api_key_id:
                job_ids.add(j.get("id"))
        total = 0
        for d in crawl_docs:
            if d.get("crawl_job_id") in job_ids:
                dt = _parse_dt(d.get("created_at"))
                if dt and _day_key(dt) == day:
                    try:
                        total += int(d.get("characters_extracted") or 0)
                    except Exception:
                        pass
        return total

    def _rate_limited(search_reqs, crawl_jobs, api_key_id, rps, now_dt):
        # Soft RPS: count requests in last 1 second window based on created_at
        if not rps or rps <= 0:
            return False
        window_start = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for r in search_reqs:
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt > window_start:
                cnt += 1
        for j in crawl_jobs:
            if j.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(j.get("created_at"))
            if dt and dt > window_start:
                cnt += 1
        return cnt >= float(rps)

    def _normalize_domain(url):
        try:
            from urllib.parse import urlparse
            h = urlparse(url).hostname
            return h.lower() if h else None
        except Exception:
            return None

    def _log_request(search_requests, row):
        search_requests.append(row)
        _save("search_requests.json", search_requests)

    t0 = time.time()
    now_iso = _now_iso()
    now_dt = _parse_dt(now_iso) or datetime.datetime.now(datetime.timezone.utc)

    # Validate inputs
    if not isinstance(companyName, str) or not companyName.strip():
        return _err("VALIDATION_ERROR", "companyName is required and must be a non-empty string")
    if industry is not None and not isinstance(industry, str):
        return _err("VALIDATION_ERROR", "industry must be a string when provided")
    if numResults is None:
        num = 5
    else:
        if not isinstance(numResults, (int, float)) or isinstance(numResults, bool):
            return _err("VALIDATION_ERROR", "numResults must be a positive number")
        if numResults <= 0:
            return _err("VALIDATION_ERROR", "numResults must be a positive number")
        num = int(numResults)
    if num < 1 or num > 50:
        return _err("VALIDATION_ERROR", "numResults must be between 1 and 50")

    # Load store
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    crawl_jobs = _load("crawl_jobs.json")
    crawl_docs = _load("crawl_documents.json")

    key = _pick_active_key(api_keys)
    if not key:
        return _err("UNAUTHORIZED", "No active API key is available to serve this request")

    api_key_id = key.get("id")
    if not api_key_id:
        return _err("UNAUTHORIZED", "No active API key is available to serve this request")

    # Rate limit
    if _rate_limited(search_requests, crawl_jobs, api_key_id, key.get("rate_limit_rps"), now_dt):
        # minimal audit log: persist failed search_request row
        req_id = _gen_id("srch")
        row = {
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": "competitor_finder_exa",
            "vertical": "competitors",
            "query": None,
            "company_name": companyName.strip(),
            "industry": industry.strip() if isinstance(industry, str) and industry.strip() else (industry if industry is not None else None),
            "search_type": None,
            "num_results_requested": num,
            "status": "failed",
            "error_code": "RATE_LIMITED",
            "error_message": "Rate limit exceeded",
            "upstream_request_id": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "results_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        _log_request(search_requests, row)
        # update api key last_used_at even on limited attempt
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Daily quota requests
    day = _day_key(now_dt)
    used_reqs = _count_daily_requests(search_requests, crawl_jobs, api_key_id, day)
    if used_reqs + 1 > int(key.get("quota_requests_per_day") or 0):
        req_id = _gen_id("srch")
        row = {
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": "competitor_finder_exa",
            "vertical": "competitors",
            "query": None,
            "company_name": companyName.strip(),
            "industry": industry.strip() if isinstance(industry, str) and industry.strip() else (industry if industry is not None else None),
            "search_type": None,
            "num_results_requested": num,
            "status": "failed",
            "error_code": "QUOTA_EXCEEDED",
            "error_message": "Daily request quota exceeded",
            "upstream_request_id": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "results_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        _log_request(search_requests, row)
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Persist request as running then succeeded
    req_id = _gen_id("srch")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "competitor_finder_exa",
        "vertical": "competitors",
        "query": None,
        "company_name": companyName.strip(),
        "industry": industry.strip() if isinstance(industry, str) and industry.strip() else (industry if industry is not None else None),
        "search_type": None,
        "num_results_requested": num,
        "status": "running",
        "error_code": None,
        "error_message": None,
        "upstream_request_id": _gen_id("up"),
        "started_at": now_iso,
        "finished_at": None,
        "latency_ms": None,
        "results_count": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_request(search_requests, req_row)

    # Generate deterministic-ish competitor URLs
    def _slug(s):
        s = s.lower().strip()
        s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
        return s or "company"

    base = _slug(companyName)
    ind = _slug(industry) if isinstance(industry, str) and industry.strip() else None

    results = []
    for i in range(1, num + 1):
        slug = f"{base}-competitor-{i}"
        if ind:
            slug = f"{slug}-{ind}"
        url = f"https://example.com/competitor/{slug}"
        title = f"Competitor {i} of {companyName.strip()}"
        snippet = f"Potential competitor in {industry.strip()}." if ind else f"Potential competitor for {companyName.strip()}."
        results.append({
            "rank": i,
            "url": url,
            "domain": _normalize_domain(url),
            "title": title,
            "snippet": snippet,
            "published_at": None,
            "author": None,
            "source_type": "company",
            "entity_metadata": {"company_name": title.replace("Competitor ", "").strip()},
            "relevance_score": float(max(0.0, (num - i + 1) / max(1, num))),
        })

    # Persist search_results rows
    now2_iso = _now_iso()
    for r in results:
        sr_id = _gen_id("sres")
        search_results.append({
            "id": sr_id,
            "search_request_id": req_id,
            "rank": int(r["rank"]),
            "url": r["url"],
            "domain": r.get("domain"),
            "title": r.get("title"),
            "snippet": r.get("snippet"),
            "published_at": r.get("published_at"),
            "author": r.get("author"),
            "source_type": "company",
            "entity_metadata": r.get("entity_metadata"),
            "relevance_score": r.get("relevance_score"),
            "created_at": now2_iso,
            "updated_at": now2_iso,
        })
    _save("search_results.json", search_results)

    # Update request row to succeeded
    latency_ms = int((time.time() - t0) * 1000)
    for rr in search_requests:
        if rr.get("id") == req_id:
            rr["status"] = "succeeded"
            rr["finished_at"] = _now_iso()
            rr["latency_ms"] = latency_ms
            rr["results_count"] = len(results)
            rr["updated_at"] = rr["finished_at"]
            break
    _save("search_requests.json", search_requests)

    # Update api key last_used_at
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = k["last_used_at"]
            break
    _save("api_keys.json", api_keys)

    return {
        "request": {"id": req_id, "status": "succeeded", "vertical": "competitors", "num_results": len(results)},
        "results": results,
    }

