            "created_at": now_iso,
            "updated_at": now_iso,
        }
        _log_request(search_requests, row)
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Daily request quota
    day = _day_key(now_dt)
    used_reqs = _count_daily_requests(search_requests, crawl_jobs, api_key_id, day)
    if used_reqs + 1 > int(key.get("quota_requests_per_day") or 0):
        req_id = _gen_id("srch")
        row = {
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": "github_search_exa",
            "vertical": "github",
            "query": query.strip(),
            "company_name": None,
            "industry": None,
            "search_type": st,
            "num_results_requested": num,
            "status": "failed",
            "error_code": "QUOTA_EXCEEDED",
            "error_message": "Daily request quota exceeded",
            "upstream_request_id": None,
            "started_at": now_iso,
            "finished_at": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "results_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        _log_request(search_requests, row)
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Persist running
    req_id = _gen_id("srch")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "github_search_exa",
        "vertical": "github",
        "query": query.strip(),
        "company_name": None,
        "industry": None,
        "search_type": st,
        "num_results_requested": num,
        "status": "running",
        "error_code": None,
        "error_message": None,
        "upstream_request_id": _gen_id("up"),
        "started_at": now_iso,
        "finished_at": None,
        "latency_ms": None,
        "results_count": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_request(search_requests, req_row)

    def _slug(s):
        s = s.lower().strip()
        s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
        return s or "q"

    qslug = _slug(query)
    results = []
    for i in range(1, num + 1):
        if st == "users":
            url = f"https://github.com/{qslug}{i}"
            title = f"{query.strip()} (User) #{i}"
            meta = {"type": "user", "login": f"{qslug}{i}"}
        elif st == "code":
            url = f"https://github.com/search?q={qslug}&type=code&p={i}"
            title = f"Code search for {query.strip()} #{i}"
            meta = {"type": "code", "query": query.strip(), "page": i}
        elif st == "repositories":
            url = f"https://github.com/{qslug}/repo-{i}"
            title = f"{query.strip()} (Repository) #{i}"
            meta = {"type": "repository", "full_name": f"{qslug}/repo-{i}", "stars": max(0, (num - i) * 10)}
        else:
            # all: cycle repository/user/code
            if i % 3 == 1:
                url = f"https://github.com/{qslug}/repo-{i}"
                title = f"{query.strip()} (Repository) #{i}"
                meta = {"type": "repository", "full_name": f"{qslug}/repo-{i}", "stars": max(0, (num - i) * 10)}
            elif i % 3 == 2:
                url = f"https://github.com/{qslug}{i}"
                title = f"{query.strip()} (User) #{i}"
                meta = {"type": "user", "login": f"{qslug}{i}"}
            else:
                url = f"https://github.com/search?q={qslug}&type=code&p={i}"
                title = f"Code search for {query.strip()} #{i}"
                meta = {"type": "code", "query": query.strip(), "page": i}

        snippet = f"GitHub {meta['type']} result for '{query.strip()}'."
        results.append({
            "rank": i,
            "url": url,
            "domain": _normalize_domain(url),
            "title": title,
            "snippet": snippet,
            "published_at": None,
            "author": None,
            "source_type": "github",
            "entity_metadata": meta,
            "relevance_score": float(max(0.0, (num - i + 1) / max(1, num))),
        })

    # Persist results
    now2_iso = _now_iso()
    for r in results:
        search_results.append({
            "id": _gen_id("sres"),
            "search_request_id": req_id,
            "rank": int(r["rank"]),
            "url": r["url"],
            "domain": r.get("domain"),
            "title": r.get("title"),
            "snippet": r.get("snippet"),
            "published_at": r.get("published_at"),
            "author": r.get("author"),
            "source_type": "github",
            "entity_metadata": r.get("entity_metadata"),
            "relevance_score": r.get("relevance_score"),
            "created_at": now2_iso,
            "updated_at": now2_iso,
        })
    _save("search_results.json", search_results)

    # Update request succeeded
    latency_ms = int((time.time() - t0) * 1000)
    for rr in search_requests:
        if rr.get("id") == req_id:
            rr["status"] = "succeeded"
            rr["finished_at"] = _now_iso()
            rr["latency_ms"] = latency_ms
            rr["results_count"] = len(results)
            rr["updated_at"] = rr["finished_at"]
            break
    _save("search_requests.json", search_requests)

    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = k["last_used_at"]
            break
    _save("api_keys.json", api_keys)

    return {
        "request": {"id": req_id, "status": "succeeded", "vertical": "github", "num_results": len(results)},
        "results": results,
    }

def list_search_requests_exa(apiKey, status=None, vertical=None, toolName=None, createdAfter=None, createdBefore=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            return base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
        except Exception:
            return None

    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    def _ensure_audit_collections():
        # Vendor schema doesn't declare an audit log; persist to a local request log for dynamics.
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    audit_file = _ensure_audit_collections()

    def _log(api_key_id, key_prefix, outcome_code, httpish_status, latency_ms, details=None):
        logs = _load(audit_file)
        rid = f"reqlog_{int(now.timestamp()*1000)}_{len(logs)+1}"
        row = {
            "id": rid,
            "timestamp": now_iso,
            "tool_name": "list_search_requests_exa",
            "api_key_id": api_key_id,
            "key_prefix": key_prefix,
            "status": outcome_code,
            "http_status": httpish_status,
            "latency_ms": int(latency_ms),
            "details": details or {}
        }
        logs.append(row)
        _save(audit_file, logs)

    def _resolve_key(apiKey_value):
        keys = _load("api_keys.json")
        if not isinstance(apiKey_value, str) or not apiKey_value.strip():
            return None
        val = apiKey_value.strip()
        for k in keys:
            if k.get("id") == val or k.get("key_prefix") == val:
                return k
        return None

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log(None, None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    allowed_vertical = {"web", "papers", "company", "competitors", "linkedin", "wikipedia", "github"}
    allowed_tool = {"web_search_exa", "research_paper_search_exa", "company_research_exa", "competitor_finder_exa",
                    "linkedin_search_exa", "wikipedia_search_exa", "github_search_exa"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

    if vertical is not None and (not isinstance(vertical, str) or vertical not in allowed_vertical):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "vertical"})
        return _err("VALIDATION_ERROR", "Invalid vertical filter", field="vertical")

    if toolName is not None and (not isinstance(toolName, str) or toolName not in allowed_tool):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "toolName"})
        return _err("VALIDATION_ERROR", "Invalid toolName filter", field="toolName")

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageSize"})
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200", field="pageSize")

    if pageToken is not None and (not isinstance(pageToken, str) or not pageToken.strip()):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
        return _err("VALIDATION_ERROR", "pageToken must be a non-empty string when provided", field="pageToken")

    try:
        created_after_dt = _parse_dt(createdAfter, "createdAfter")
        created_before_dt = _parse_dt(createdBefore, "createdBefore")
    except ValueError as e:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "createdAfter/createdBefore"})
        return _err("VALIDATION_ERROR", str(e))

    if created_after_dt and created_before_dt and created_after_dt > created_before_dt:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "createdAfter/createdBefore"})
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore")

    # Authenticate (explicit credential parameter)
    key = _resolve_key(apiKey)
    if not key or key.get("status") != "active":
        _log(key.get("id") if key else None, key.get("key_prefix") if key else None, "UNAUTHORIZED", 401, (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "API key is invalid or not active")

    # Update last_used_at
    keys = _load("api_keys.json")
    for kk in keys:
        if kk.get("id") == key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            key = kk
            break
    _save("api_keys.json", keys)

    # Rate limit enforcement (soft, per key)
    rps = key.get("rate_limit_rps")
    try:
        rps = float(rps)
    except Exception:
        rps = None
    if rps and rps > 0:
        logs = _load(audit_file)
        window_start = now - datetime.timedelta(seconds=1)
        recent = 0
        for row in reversed(logs):
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt < window_start:
                break
            if row.get("api_key_id") == key.get("id"):
                recent += 1
        if recent >= rps:
            _log(key.get("id"), key.get("key_prefix"), "RATE_LIMIT", 429, (time.time() - t0) * 1000)
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Read & filter
    reqs = _load("search_requests.json")
    filtered = []
    for r in reqs:
        if r.get("api_key_id") != key.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if toolName is not None and r.get("tool_name") != toolName:
            continue
        if vertical is not None:
            # Tool parameter uses "papers" but storage uses "research_papers"
            v = vertical
            if v == "papers":
                v = "research_papers"
            if r.get("vertical") != v:
                continue
        if created_after_dt or created_before_dt:
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
                if rdt.tzinfo is None:
                    rdt = rdt.replace(tzinfo=datetime.timezone.utc)
                rdt = rdt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if created_after_dt and rdt < created_after_dt:
                continue
            if created_before_dt and rdt >= created_before_dt:
                continue
        filtered.append(r)

    # Sort by created_at desc (stable)
    def _dt_key(row):
        s = row.get("created_at")
        if isinstance(s, str):
            try:
                dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered.sort(key=_dt_key, reverse=True)

    # Pagination via cursor = base64("created_at|id")
    start_idx = 0
    if pageToken:
        decoded = _b64d(pageToken.strip())
        if not decoded or "|" not in decoded:
            _log(key.get("id"), key.get("key_prefix"), "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
            return _err("VALIDATION_ERROR", "Invalid pageToken", field="pageToken")
        token_created, token_id = decoded.split("|", 1)
        # find position AFTER that item in the current filtered+sorted view
        found = False
        for i, r in enumerate(filtered):
            if r.get("id") == token_id and r.get("created_at") == token_created:
                start_idx = i + 1
                found = True
                break
        if not found:
            _log(key.get("id"), key.get("key_prefix"), "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
            return _err("VALIDATION_ERROR", "pageToken is no longer valid for this query", field="pageToken")

    page = filtered[start_idx:start_idx + pageSize]
    has_more = (start_idx + pageSize) < len(filtered)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _b64e(f"{last.get('created_at')}|{last.get('id')}")

    latency_ms = (time.time() - t0) * 1000
    _log(key.get("id"), key.get("key_prefix"), "OK", 200, latency_ms, {"returned": len(page), "total": len(filtered)})

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "page_size": pageSize,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def get_search_request_exa(apiKey, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # Validation
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    key_val = apiKey.strip()
    req_id = id.strip()

    # Resolve credential: allow api_keys.id or api_keys.key_prefix
    key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == key_val or k.get("key_prefix") == key_val)), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    now_iso = _iso(_now())
    # Update key last_used_at regardless of hit/miss (observable dynamics)
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            nk = dict(k)
            nk["last_used_at"] = now_iso
            nk["updated_at"] = now_iso
            api_keys[i] = nk
            break

    # Find by id; then enforce ownership. If not owned, behave like NOT_FOUND.
    row = next((r for r in search_requests if isinstance(r, dict) and r.get("id") == req_id), None)

    # Minimal audit log (this service uses search_requests itself as request log; for reads we only stamp key usage)
    _save("api_keys.json", api_keys)

    if not row or row.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "search_request id not found for this API key")

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": row, "meta": {"latency_ms": latency_ms}}

def list_search_results_exa(apiKey, searchRequestId, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _decode_token(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str) or not tok.strip():
            return 0
        s = tok.strip()
        # accept either our base64 cursor or plain integer offsets (relaxed)
        if s.isdigit():
            try:
                return max(0, int(s))
            except Exception:
                return 0
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                off = int(raw.split(":", 1)[1])
                return off if off >= 0 else 0
        except Exception:
            return 0
        return 0

    def _encode_token(offset):
        raw = f"offset:{int(offset)}"
        return base64.urlsafe_b64encode(raw.encode("utf-8")).decode("utf-8").rstrip("=")

    # Validation
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(searchRequestId, str) or not searchRequestId.strip():
        return _err("VALIDATION_ERROR", "searchRequestId must be a non-empty string")

    if pageSize is None:
        ps = 50
    else:
        if not isinstance(pageSize, int) or isinstance(pageSize, bool):
            return _err("VALIDATION_ERROR", "pageSize must be an integer")
        if pageSize < 1 or pageSize > 200:
            return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200")
        ps = pageSize

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")

    key_val = apiKey.strip()
    sreq_id = searchRequestId.strip()

    # Authenticate
    key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == key_val or k.get("key_prefix") == key_val)), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    now_iso = _iso(_now())
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            nk = dict(k)
            nk["last_used_at"] = now_iso
            nk["updated_at"] = now_iso
            api_keys[i] = nk
            break

    # Existence + ownership: if not owned, treat as NOT_FOUND per tool contract
    sreq = next((r for r in search_requests if isinstance(r, dict) and r.get("id") == sreq_id), None)
    _save("api_keys.json", api_keys)
    if not sreq or sreq.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "search_request_id not found for this API key")

    # Filter + order
    rows = [r for r in search_results if isinstance(r, dict) and r.get("search_request_id") == sreq_id]
    rows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

    offset = _decode_token(pageToken)
    if offset > len(rows):
        offset = len(rows)

    page = rows[offset:offset + ps]
    next_off = offset + len(page)
    has_more = next_off < len(rows)
    next_token = _encode_token(next_off) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "page_size": ps,
            "offset": offset,
            "has_more": has_more,
            "next_page_token": next_token,
            "latency_ms": latency_ms,
        },
    }

def list_crawl_jobs_exa(apiKey, status=None, createdAfter=None, createdBefore=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            return base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
        except Exception:
            return None

    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    def _ensure_audit_collections():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])
        return "request_logs.json"

    audit_file = _ensure_audit_collections()

    def _log(api_key_id, key_prefix, outcome_code, httpish_status, latency_ms, details=None):
        logs = _load(audit_file)
        rid = f"reqlog_{int(datetime.datetime.now(datetime.timezone.utc).timestamp()*1000)}_{len(logs)+1}"
        logs.append({
            "id": rid,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "tool_name": "list_crawl_jobs_exa",
            "api_key_id": api_key_id,
            "key_prefix": key_prefix,
            "status": outcome_code,
            "http_status": httpish_status,
            "latency_ms": int(latency_ms),
            "details": details or {}
        })
        _save(audit_file, logs)

    def _resolve_key(apiKey_value):
        keys = _load("api_keys.json")
        if not isinstance(apiKey_value, str) or not apiKey_value.strip():
            return None
        val = apiKey_value.strip()
        for k in keys:
            if k.get("id") == val or k.get("key_prefix") == val:
                return k
        return None

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log(None, None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageSize"})
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200", field="pageSize")

    if pageToken is not None and (not isinstance(pageToken, str) or not pageToken.strip()):
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
        return _err("VALIDATION_ERROR", "pageToken must be a non-empty string when provided", field="pageToken")

    try:
        created_after_dt = _parse_dt(createdAfter, "createdAfter")
        created_before_dt = _parse_dt(createdBefore, "createdBefore")
    except ValueError as e:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "createdAfter/createdBefore"})
        return _err("VALIDATION_ERROR", str(e))

    if created_after_dt and created_before_dt and created_after_dt > created_before_dt:
        k = _resolve_key(apiKey)
        _log(k.get("id") if k else None, k.get("key_prefix") if k else None, "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "createdAfter/createdBefore"})
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore")

    # Authenticate
    key = _resolve_key(apiKey)
    if not key or key.get("status") != "active":
        _log(key.get("id") if key else None, key.get("key_prefix") if key else None, "UNAUTHORIZED", 401, (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "API key is invalid or not active")

    # Update last_used_at
    keys = _load("api_keys.json")
    for kk in keys:
        if kk.get("id") == key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            key = kk
            break
    _save("api_keys.json", keys)

    # Rate limit enforcement
    rps = key.get("rate_limit_rps")
    try:
        rps = float(rps)
    except Exception:
        rps = None
    if rps and rps > 0:
        logs = _load(audit_file)
        window_start = now_dt - datetime.timedelta(seconds=1)
        recent = 0
        for row in reversed(logs):
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt < window_start:
                break
            if row.get("api_key_id") == key.get("id"):
                recent += 1
        if recent >= rps:
            _log(key.get("id"), key.get("key_prefix"), "RATE_LIMIT", 429, (time.time() - t0) * 1000)
            return _err("RATE_LIMIT", "Rate limit exceeded")

    jobs = _load("crawl_jobs.json")
    filtered = []
    for j in jobs:
        if j.get("api_key_id") != key.get("id"):
            continue
        if status is not None and j.get("status") != status:
            continue
        if created_after_dt or created_before_dt:
            ca = j.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                jdt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
                if jdt.tzinfo is None:
                    jdt = jdt.replace(tzinfo=datetime.timezone.utc)
                jdt = jdt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if created_after_dt and jdt < created_after_dt:
                continue
            if created_before_dt and jdt >= created_before_dt:
                continue
        filtered.append(j)

    def _dt_key(row):
        s = row.get("created_at")
        if isinstance(s, str):
            try:
                dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered.sort(key=_dt_key, reverse=True)

    # Pagination cursor = base64("created_at|id")
    start_idx = 0
    if pageToken:
        decoded = _b64d(pageToken.strip())
        if not decoded or "|" not in decoded:
            _log(key.get("id"), key.get("key_prefix"), "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
            return _err("VALIDATION_ERROR", "Invalid pageToken", field="pageToken")
        token_created, token_id = decoded.split("|", 1)
        found = False
        for i, r in enumerate(filtered):
            if r.get("id") == token_id and r.get("created_at") == token_created:
                start_idx = i + 1
                found = True
                break
        if not found:
            _log(key.get("id"), key.get("key_prefix"), "VALIDATION_ERROR", 400, (time.time() - t0) * 1000, {"field": "pageToken"})
            return _err("VALIDATION_ERROR", "pageToken is no longer valid for this query", field="pageToken")

    page = filtered[start_idx:start_idx + pageSize]
    has_more = (start_idx + pageSize) < len(filtered)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _b64e(f"{last.get('created_at')}|{last.get('id')}")

    latency_ms = (time.time() - t0) * 1000
    _log(key.get("id"), key.get("key_prefix"), "OK", 200, latency_ms, {"returned": len(page), "total": len(filtered)})

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "page_size": pageSize,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def get_crawl_job_exa(apiKey, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # Validation
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_keys = _load("api_keys.json")
    crawl_jobs = _load("crawl_jobs.json")

    key_val = apiKey.strip()
    job_id = id.strip()

    # Authenticate
    key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == key_val or k.get("key_prefix") == key_val)), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    now_iso = _iso(_now())
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            nk = dict(k)
            nk["last_used_at"] = now_iso
            nk["updated_at"] = now_iso
            api_keys[i] = nk
            break

    job = next((r for r in crawl_jobs if isinstance(r, dict) and r.get("id") == job_id), None)
    _save("api_keys.json", api_keys)

    if not job or job.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "crawl_job id not found for this API key")

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": job, "meta": {"latency_ms": latency_ms}}

def cancel_job_exa(apiKey, jobType, id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0531000" if __import__("os").path.isdir("./environment_mix/0531000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # Validation
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if jobType not in ("search_request", "crawl_job"):
        return _err("VALIDATION_ERROR", "jobType must be one of: search_request, crawl_job")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")
    if isinstance(reason, str) and not reason.strip():
        reason = None

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    crawl_jobs = _load("crawl_jobs.json")

    key_val = apiKey.strip()
    job_id = id.strip()

    # Authenticate
    key_row = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == key_val or k.get("key_prefix") == key_val)), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    now_iso = _iso(_now())
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            nk = dict(k)
            nk["last_used_at"] = now_iso
            nk["updated_at"] = now_iso
            api_keys[i] = nk
            break

    # Select and find job
    if jobType == "search_request":
        coll_file = "search_requests.json"
        rows = search_requests
    else:
        coll_file = "crawl_jobs.json"
        rows = crawl_jobs

    idx = None
    job = None
    for i, r in enumerate(rows):
        if isinstance(r, dict) and r.get("id") == job_id:
            idx = i
            job = r
            break

    # Persist key usage even on miss (observable dynamics)
    _save("api_keys.json", api_keys)

    if job is None or job.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", f"{jobType} id not found for this API key")

    # Lifecycle transition enforcement: only queued/running -> cancelled
    cur = job.get("status")
    allowed = {"queued", "running"}
    if cur not in allowed:
        return _err(
            "INVALID_TRANSITION",
            f"Cannot cancel a {jobType} in status '{cur}'. Business rule: only queued or running jobs can be cancelled.",
            from_status=cur,
            to_status="cancelled",
        )

    updated = dict(job)
    updated["status"] = "cancelled"
    updated["updated_at"] = now_iso
    updated["finished_at"] = updated.get("finished_at") or now_iso
    # For search_requests / crawl_jobs: cancellation reason goes into error_message when applicable
    if reason is not None:
        updated["error_message"] = reason
    if not updated.get("error_code"):
        updated["error_code"] = "USER_CANCELLED" if jobType == "search_request" else "CANCELLED_BY_USER"

    # If job had started_at unset, leave it as-is (some queued jobs never started)
    if updated.get("started_at") is None and cur == "running":
        updated["started_at"] = now_iso

    rows[idx] = updated
    _save(coll_file, rows)

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": updated, "meta": {"latency_ms": latency_ms}}
